export function debounce(fn: (...args: any[]) => void, waitMs: number) {
    let timer: ReturnType<typeof setTimeout> | null = null;
    return (...args: any[]) => {
        if (timer !== null) {
            clearTimeout(timer); // cancel previous timer
        }
        timer = setTimeout(() => fn(args), waitMs);
    };
}
```

The key fixes:
1. Cancel the previous timer with `clearTimeout(timer)` instead of just returning early
2. Don't reset `timer = null` immediately after scheduling — the timer still holds the pending call
3. When the timer fires, it will be `null` after execution (since `setTimeout` returns a timer ID that we can clear, but we need to handle the case where it fires)

