content.text:
export function debounce(fn: (...args: any[]) => void, waitMs: number) {
    let timer: ReturnType<typeof setTimeout> | null = null;
    return (...args: any[]) => {
        if (timer !== null) {
            clearTimeout(timer); // cancel any pending previous call
        }
        timer = setTimeout(() => {
            timer = null; // clear timer when it fires
            fn(args);
        }, waitMs);
    };
}

// ── Self-test ──────────────────────────────────────────────
import assert from 'node:assert';

let calls: number[] = [];
const debounced = debounce(() => {
    calls.push(Date.now());
}, 50);

// Rapidly call more than once within the wait window
debounced(1);
debounced(2);
debounced(3);

// Wait for the debounce window to expire (use generous delay)
setTimeout(() => {
    // Only one call should have happened (with latest args)
    assert.strictEqual(calls.length, 1, `Expected 1 call, got ${calls.length}`);
    assert.strictEqual(calls[0], 3, `Expected last arg 3, got ${calls[0]}`);

    // Verify cancellation: a new call should cancel the pending one
    const callsAfterCancel: number[] = [];
    const debounced2 = debounce(() => {
        callsAfterCancel.push(Date.now());
    }, 50);

    debounced2(10);
    debounced2(20);
    debounced2(30);
    setTimeout(() => {
        assert.strictEqual(callsAfterCancel.length, 1, `Expected 1 call after cancel, got ${callsAfterCancel.length}`);
        assert.strictEqual(callsAfterCancel[0], 30, `Expected last arg 30, got ${callsAfterCancel[0]}`);

        console.log('all tests passed');
    }, 100);
}, 0);

